#!/usr/bin/env bash
# goaiez-plan-part3.sh - part 3 of 3 of GOAIEZ-MASTER-PLAN.md
#
# ⭐⭐⭐ THIS VERSION CARRIES R243 · R245 · R246 · §264W · §264X.
#   R245 the standing delegation · R246 the line "not gated" does not cross ·
#   the 7 owner facts · the 24 delegated rulings · X-216 permanently retired.
#
# ⛔ The PREVIOUS parts (sha 8bae92b4...) predate all of that. Running them
#   would OVERWRITE the patched plan with the older one.
#
#   Run all three, in any order. The last assembles and checksums.
set -euo pipefail
ok(){ printf '  \033[32m/\033[0m %s\n' "$*"; }
die(){ printf '\n  \033[31mX %s\033[0m\n\n' "$*"; exit 1; }
DEST="${1:-}"; [ -n "$DEST" ] || die "Usage: bash goaiez-plan-part3.sh /path/to/tree"
[ -f "$DEST/artisan" ] || die "No 'artisan' in $DEST"
D="$DEST/.goaiez-plan-parts"; mkdir -p "$D"
sed -n '/^__PART__$/,$p' "$0" | tail -n +2 > "$D/part3.b64"
ok "part 3 of 3 received"
HAVE=$(ls "$D"/part*.b64 2>/dev/null | wc -l | tr -d ' ')
printf '  parts present: %s of 3\n' "$HAVE"
[ "$HAVE" -lt 3 ] && { printf '\n  Run the remaining part(s).\n\n'; exit 0; }
cat "$D"/part1.b64 "$D"/part2.b64 "$D"/part3.b64 | base64 -d | xz -d > "$D/plan.tmp" 2>/dev/null || die "decompression failed"
A=$(sha256sum "$D/plan.tmp" | cut -d' ' -f1)
[ "$A" = "02649b287d9b15521e2aeb41d996eed314b7d841407d34183c9c2f57ee77449a" ] || die "checksum MISMATCH - re-download all three parts"
mv "$D/plan.tmp" "$DEST/GOAIEZ-MASTER-PLAN.md"; rm -rf "$D"
ok "GOAIEZ-MASTER-PLAN.md written and checksum-verified (R245/R246 included)"
printf '  %s bytes\n\n  Next:  php artisan module:scaffold\n\n' "$(wc -c < "$DEST/GOAIEZ-MASTER-PLAN.md")"
exit 0

__PART__

